const items = $input.all();
const result = [];

for (const item of items) {
  const body = item.json.body || item.json;
  const error = body.error || 'Unknown Error';
  const line = body.line || 'N/A';
  const repo = body.repo || 'unknown-repo';
  const stackTrace = body.stackTrace || '';

  const cleanedTrace = stackTrace
    .split('\n')
    .filter(line => line.trim().length > 0)
    .join('\n');

  const errorContext = {
    errorType: error,
    lineNumber: line,
    repository: repo,
    stackTrace: cleanedTrace,
    timestamp: new Date().toISOString(),
    severity: error.toLowerCase().includes('null') ? 'HIGH' : 'MEDIUM'
  };

  result.push({ json: errorContext });
}

return result;

